    ["the_deadmines"] = {
        { 92747, "A", 9, 16, "Alba Fairmoon", "Westfall 52.4,53", nil, false, {92745}, nil, "Collect 8 Suspicious Industrial Supplies from Moonbrook. The crates are not on the town streets — they are inside the building leading to the Deadmines entrance, down the path into the cave.", "Part of the toxin-investigation chain: samples from several mines all point to the Deadmines beneath Moonbrook. Collect supplies in Moonbrook and turn them in to Alba Fairmoon, which starts the explosives-materiel phase. Sample points of the prerequisite ring 'Log Test': Morlsen Farm 46.2,38.3 and Jensen Farm 56.7,18.7. ◎ The supply crates are in the cave on the way to the Deadmines entrance, and scattered in buildings all over Moonbrook (including the Moonbrook schoolhouse) — no elites need to be fought.", {{9,1}, {12,2}, {14,3}, {19,4}, {23,5}}, nil, nil, 253092, "Alba Fairmoon", { xp = 575, money = 400, rep = { {72, 50, "Stormwind City"} } } },
