        { 92819, "A", 9, 18, "Alba Fairmoon", "Westfall - the hill behind Moonbrook 38.6,83.2", "Destruction in Deadmines", false, {92753}, nil, "Use the remote detonator to set off the charge placed beside the furnace.", "The closing step of \"Demolition of the Deadmines\": after rendezvousing with Alba Fairmoon on the hill behind Moonbrook, finish it off with the detonator.", {{9,1}, {14,2}, {16,3}, {21,4}, {25,5}}, nil, nil, 253279, "Alba Fairmoon", { rep = { {72, 50, "Stormwind City"} } } },
        { 166, "A", 14, 22, "Marshal Gryan Stoutmantle", "Westfall - Sentinel Hill 56,47", "Red Silk Bandanas", false, {155}, {6087, 2041, 2042}, "Kill Edwin VanCleef and bring his head back to Marshal Gryan Stoutmantle.", "The whole chain starts with Marshal Gryan Stoutmantle (Westfall - Sentinel Hill 56,47). VanCleef is the final boss of the Deadmines, on the top deck of the ship.", {{14,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {3637}, nil, 234, "Marshal Gryan Stoutmantle", { xp = 2600, rep = { {72, 200, "Stormwind City"} } } },
        { 168, "A", 14, 18, "Wilder Thistlenettle", "Stormwind City - Dwarven District 70,41", nil, false, nil, {2037, 2036, 270007}, "Collect 4 Miners' Union Membership Cards and bring them to Wilder Thistlenettle in Stormwind City.", "Union cards drop from the undead near the dungeon entrance. ◎ The drop rate is very low and they are NOT shared among the group (everyone loots their own) — expect a long grind.", {{14,2}, {16,3}, {21,4}, {25,5}}, {1894}, nil, 656, "Wilder Thistlenettle", { xp = 1350, rep = { {47, 100, "Ironforge"} } } },
        { 214, "A", 14, 17, "Scout Riell", "Westfall - Sentinel Hill 56, 47", "Red Silk Bandanas", false, {155}, {2074, 2089, 6094, 270005}, "Collect 10 Red Silk Bandanas and bring them to Scout Riell in the watchtower of Sentinel Hill.", "The miners inside and outside the dungeon all drop bandanas. You must complete \"The Defias Traitor\" escort first before this quest opens.", {{14,2}, {15,3}, {20,4}, {24,5}}, {915}, nil, 820, "Scout Riell", { xp = 1250, rep = { {72, 100, "Stormwind City"} } } },
        { 167, "A", 15, 20, "Wilder Thistlenettle", "Stormwind City - Dwarven District 70,41", nil, false, nil, {1893, 270012, 270013}, "Retrieve the Explorer's League badge and bring it to Wilder Thistlenettle in Stormwind City.", "Badges drop from Foreman Thistlenettle right by the dungeon entrance. ◎ For solo runs wait until level 23 or so: the elites hit hard and chain-pull, and the quest mob is linked to another add.", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {1875}, nil, 656, "Wilder Thistlenettle", { xp = 1550, money = 500, rep = { {47, 100, "Ironforge"} } } },
        { 2040, "A", 15, 20, "Shoni the Shilent", "Stormwind City - Dwarven District 62,34", "Shoni the Shilent", false, {2041}, {7606, 7607, 270015, 270016}, "Retrieve the Compact High-Energy Engine from the Deadmines and bring it to Shoni the Shilent in the Dwarven District of Stormwind City.", "This quest can be taken directly, or you can first do the intro quest from Nogg (Ironforge - Tinker Town 69,50). The engine drops from Sneed's Shredder.", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {7365}, nil, 6579, "Shoni the Shilent", { xp = 1550, rep = { {72, 100, "Stormwind City"}, {54, 100, "Gnomeregan Exiles"} } } },
