        { 95772, nil, 24, 31, "多林·桑布雷德", "Redridge Mountains - Lakeshire 25.6,46.6", nil, false, nil, nil, "到维尔加挖掘场一带寻找多林·桑布雷德的兄弟戴温。", "Daywin went into the excavation site with the prospecting crew; his body can be found inside the dungeon to pick up the follow-up quest. ◎ The quest giver is in the Lakeshire stables — on the left as you cross the bridge from the flight master (player-reported).", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 956, "多林·桑布雷德", { xp = 3150 } },
        { 98815, nil, 24, 28, "詹姆斯·哈洛兰", "Wetlands - 米奈希尔港 8,55", "日常供货", false, {469}, nil, "把 4 张灌木丛迅猛龙皮交给米奈希尔港的制皮匠詹姆斯·哈洛兰。", "Raptor hides drop from the raptors inside the dungeon. The prerequisite is Halloran's \"Young Crocolisk Skin\"; \"Daily Delivery\" is NOT required (player-reported, contradicts the Wowhead table).", {{24,2}, {26,3}, {31,4}, {36,5}}, nil, nil, 2094, "詹姆斯·哈洛兰", { xp = 1150, money = 1200, rep = { {72, 50, "Stormwind City"} } } },
        { 95646, "A", 24, 31, "绿色守卫者雷希耶尔", "Wetlands 56.2,40.6", nil, false, nil, {271667, 271670, 271664}, "在挖掘场杀一只高地惊魂，把它的根核带给湿地的雷希耶尔。", "The Dreadful Root Core (#270180) drops from Highland Terrors inside the dungeon; choose-one-of-three reward. ◎ Prerequisite: finish First Mate Fitzsimmons' (#1239) four-step Wetlands chain — The Greenwarden (463), Tramping Paws (276), Fire Taboo (277), Blisters on The Land (275) — before this quest is offered.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270180}, nil, 1244, "绿色守卫者雷希耶尔", { xp = 3150 } },
        { 95647, "A", 24, 31, "凯特林·格拉斯曼", "Wetlands - 米奈希尔港南 11.6,58.4", "寻找凯特林", false, {95737}, nil, "在挖掘场找到阿尔丁·格拉斯曼，弄清他遭遇了什么。", "The chain starts with \"Seeking Caitlin\" from Pethnant the Silent (#3970) in Ashenvale (35.0, 48.6).", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 1480, "凯特林·格拉斯曼", { xp = 2500 } },
        { 95795, "A", 24, 31, nil, nil, nil, true, nil, {271769, 271768}, "把戴温的命运带回湖畔镇告诉多林·桑布雷德。", "Pick up directly on Daywin's body inside the dungeon; choose one of two belt rewards.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, nil, nil, { xp = 3150 } },
        { 95697, "H", 24, 31, "Borstan", "Orgrimmar - The Drag 57.5,53.4", nil, false, nil, {280766, 280805, 250185, 250077}, "进挖掘场带回 4 块灌木丛迅猛龙肉。", "The meat (#271100) drops from raptors inside the dungeon. Giver: cooking trainer Borstan (The Drag, Orgrimmar, 57.5, 53.4). Rewards include a cooking recipe.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {271100}, nil, 3368, "Borstan", { xp = 3150 } },
        { 95664, "H", 24, 31, nil, nil, nil, false, nil, nil, "把泰坦圣物带到雷霆崖长者高地，找能鉴定它的人。", "Loot the Titan Relic (#270865) from the last boss, the Ruins Guardian, to start this quest. Multiple players confirm (Oct 2): the relic is NOT returned on turn-in.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95810, "A", 24, 31, nil, nil, nil, false, nil, nil, "把泰坦圣物带给湿地的勘察员维尔加。", "Started by looting the Titan Relic (#270865); the Alliance turn-in is Prospector Whelgar (#1077) at Whelgar's Excavation Site.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95682, "H", 24, nil, "亡灵卫兵密探", "Wetlands - hills by the dungeon entrance", nil, false, nil, {271740, 271732, 271745}, "在挖掘场杀 2 名龙喉破坏者和 4 名龙喉守卫，带着战利品回到副本外的亡灵卫兵密探处。", "Dragonmaw Dispatch (#284844) drops from Dragonmaw units inside the dungeon. The giver hides in the hills by the entrance area (confirmed). ◎ A player reports a possible prerequisite from the orc at the bottom of the stairs in Hammerfall (likely Zaruk) — unverified.", nil, {284844}, nil, 13155, "亡灵卫兵密探", nil },
        { 98823, "H", 24, nil, nil, nil, "长者知识", false, {95664}, {271766, 271767, 271719}, "把泰坦圣物带给莫高雷西北天空守望者高地的穆恩·大地之怒（Muln Earthfury）。", "Follow-up to \"Elder Knowledge\"; the relic drops from the last boss, the Ruins Guardian (#270865). ◎ Known beta bug (Oct 2-3): turning in \"Elder Knowledge\" consumes the relic, making this quest impossible to complete — and it cannot be re-picked after abandoning.", nil, {270865}, nil, nil, nil, nil },
        { 95809, "A", 24, nil, nil, nil, "灌木丛里的东西", false, {95647}, {1710, 3827, 2459, 280766}, "把编草心带回米奈希尔港交给凯特林·格拉斯曼。", "Started by the Reed-woven Heart (#270901), a token Aldin gives after completing the shrub-search quest.", nil, {270901}, nil, nil, nil, nil },
        { 98824, "A", 24, nil, "勘察员维尔加", nil, "运送失落的圣物", false, {95810}, {271716, 271767, 271766}, "把泰坦圣物带给铁炉堡探险者大厅的高级探险家玛盖拉斯（High Explorer Magellas）。", "Follow-up to \"Lost Relic Carry\", continue at Prospector Whelgar (#1077); the relic drops from the last boss, the Ruins Guardian (#270865). ◎ Same bug family (Oct 1-2): the Titan Relic is lost on the previous turn-in, preventing completion.", nil, {270865}, nil, 1077, "勘察员维尔加", nil },
    },
    ["blackfathom_deeps"] = {
        { 971, "A", 10, 23, "Gerrig Bonegrip", "Ironforge - The Forlorn Cavern 50,5", nil, false, nil, {6743}, "Bring the Lorgalis Manuscript to Gerrig Bonegrip in Ironforge.", "The manuscript lies in a pool inside the dungeon — in the water area of the turtle-king room: an underwater alcove chest on the right as you enter, guarded by 1-2 naga (single-pullable).", {{10,1}, {19,2}, {21,3}, {26,4}, {31,5}}, {5359}, nil, 2786, "Gerrig Bonegrip", { xp = 2750, rep = { {47, 50, "Ironforge"} } } },
        { 6563, "H", 17, 22, "Je'neu Sancrea", "Ashenvale - Zoram'gar Outpost 11,33", "The Essence of Aku'Mai", false, {6562}, nil, "Collect 20 Aku'mai Sapphires and bring them to Je'neu Sancrea in Ashenvale.", "The prerequisite \"Helping Je'neu Sancrea\" can be taken from Sunaman (Stonetalon Mountains - Sun Rock Retreat 47,64). The sapphires grow on the cave walls along the passage leading to the Blackfathom Deeps entrance.", {{17,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {16784}, nil, 12736, "Je'neu Sancrea", { xp = 1750, money = 1400, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 6564, "H", 17, 22, "A Damp Note", "Drops - see notes", nil, false, nil, nil, "Deliver the Damp Note to Je'neu Sancrea in Ashenvale; then kill Lorgus Jett in Blackfathom Deeps and report back.", "The note drops from the Tide Priests of Blackfathom Deeps (about 5%). Je'neu Sancrea is at Zoram'gar Outpost in Ashenvale (11,33). Lorgus Jett is inside the dungeon.", {{17,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {16790}, nil, nil, nil, { xp = 1300, money = 1100, rep = { {530, 75, "Darkspear Trolls"} } } },
        { 6565, "H", 17, 26, "Je'neu Sancrea", "Ashenvale", nil, false, {6564}, {17694, 17695}, nil, nil, {{17,1}, {22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 12736, "Je'neu Sancrea", { xp = 2650, money = 4000, rep = { {530, 150, "Darkspear Trolls"} } } },
        { 1198, nil, 18, nil, "Dawnwatcher Shaedlass", "Darnassus - Craftsmen's Terrace 55,24", nil, false, nil, nil, "Enter Blackfathom Deeps and find Argent Guard Thaelrid.", "Thaelrid is inside the dungeon. He is underwater on the southwest side of the turtle pool.", {{18,1}, {20,2}, {22,3}, {27,4}, {32,5}}, nil, nil, 4786, "Dawnwatcher Shaedlass", nil },
        { 1200, "A", 18, 27, "Argent Guard Thaelrid", "Blackfathom Deeps", "Blackfathom Villainy", true, {1198}, {7001, 7002, 270031, 270032}, "Retrieve the head of Sleepwalker Kerlis and bring it to Sentinel Selgolm in Darnassus.", "Kerlis is inside the dungeon; Selgolm is at (Darnassus - Craftsmen's Terrace 55,24). Careful: lighting the brazier next to Kerlis triggers enemy reinforcements.", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5881}, nil, 4787, "Scout Thaelrid", { xp = 3300, money = 6500, rep = { {529, 200, "Argent Dawn"}, {69, 200, "Darnassus"} } } },
        { 1275, "A", 18, 24, "Gershala Nightwhisper", "Darkshore - Auberdine 38,43", "Researching the Corruption", false, {3765}, {7003, 7004, 270021}, "Collect 8 Corrupted Brainstems for Gershala Nightwhisper in Auberdine.", "The prerequisite can be taken from Argus Nightwhisper (Stormwind City - The Park 36,67). All naga inside and outside the dungeon drop the brainstems.", {{18,1}, {20,2}, {22,3}, {27,4}, {32,5}}, {5952}, nil, 8997, "Gershala Nightwhisper", { xp = 2400, money = 3500, rep = { {69, 150, "Darnassus"} } } },
        { 6561, "H", 18, 27, "Scout Thaelrid", "Blackfathom Deeps", nil, true, nil, {7001, 7002, 270031, 270032}, "Bring the head of Sleepwalker Kerlis back to Bashana Runetotem in Thunder Bluff.", "Kerlis is inside the dungeon; Bashana Runetotem is at Thunder Bluff - Elder Rise (70,33). Careful: lighting the brazier beside Kerlis attracts enemies.", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5881}, nil, 4787, "Scout Thaelrid", { xp = 3300, money = 6500, rep = { {529, 200, "Argent Dawn"}, {81, 200, "Thunder Bluff"} } } },
        { 1199, "A", 20, 25, "Argent Guard Manados", "Darnassus - Craftsmen's Terrace 55,23", nil, false, nil, {6998, 7000, 270025}, "Collect 10 Twilight Pendants and bring them to Argent Guard Manados in Darnassus.", "Every Twilight's Hammer enemy in the dungeon drops a pendant. ◎ Players report the current turn-in awards all 3 reward items at once (likely a bug).", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {5879}, nil, 4784, "Argent Guard Manados", { xp = 2550, rep = { {529, 150, "Argent Dawn"}, {69, 150, "Darnassus"} } } },
        { 1740, nil, 20, nil, "Doan Karhan", "The Barrens 49,57", nil, false, nil, nil, "Collect 3 Shards of Solanruk's Orb and 1 Large Shard, and bring them to Duane Kahan in the Barrens.", "Warlock only! The shards drop from Twilight Acolytes in Blackfathom Deeps; the large shard drops from the Shadowfang Moonrunner wolves in Shadowfang Keep.", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {6914, 6915}, "Warlock", 6247, "Doan Karhan", nil },
        { 6921, "H", 21, 27, "Je'neu Sancrea", "Ashenvale - Zoram'gar Outpost 11,33", nil, false, nil, nil, "Bring the Core of the Deeps to Je'neu Sancrea at Zoram'gar Outpost in Ashenvale.", "The Fathom Core is in the water inside the dungeon. Once you take it, Baron Aquanis will appear and attack — he drops a quest item; bring that to Je'neu Sancrea as well. The core is underwater in the center of the big pool before the last boss (no need to enter the boss's room).", {{21,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {16762}, nil, 12736, "Je'neu Sancrea", { xp = 2750, money = 4500, rep = { {530, 150, "Darkspear Trolls"} } } },
    },
    ["the_stockade"] = {
        { 391, "A", 16, 29, "Warden Thelwater", "Stormwind City - The Stockade 51,69", "The Stockade Riots", false, {389}, nil, "Kill Bazil Thredd and bring his head to Warden Thelwater.", "See the \"Defias Brotherhood\" chain of the Deadmines for the prerequisite. Bazil Thredd is inside the dungeon.", {{16,1}, {25,2}, {27,3}, {32,4}, {37,5}}, {2926}, nil, 1719, "Warden Thelwater", { xp = 2350, money = 2500, rep = { {72, 100, "Stormwind City"} } } },
        { 377, "A", 22, 26, "Councilman Millstipe", "Duskwood - Darkshire 72,47", nil, false, nil, {2033, 2906}, "Kill Dexter Ward and bring his hand back to Councilman Millstipe of Darkshire as proof.", "Dexter Ward is inside the dungeon.", {{22,2}, {24,3}, {29,4}, {34,5}}, {3628}, nil, 270, "Councilman Millstipe", { xp = 2100, rep = { {72, 100, "Stormwind City"} } } },
        { 378, "A", 22, 27, "Motley Garmason", "Wetlands - Dun Modr 49,18", "The Fury Runs Deep", false, {303}, {3562, 1264}, "Bring the head of Kam Deepfury to Motley Garmason in Dun Modr.", "The prerequisite is also taken from Motley Garmason. Kam Deepfury is inside the dungeon.", {{22,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {3640}, nil, 1074, "Motley Garmason", { xp = 2750, rep = { {47, 150, "Ironforge"} } } },
        { 386, "A", 22, 25, "Guard Berton", "Redridge Mountains - Lakeshire 26,46", nil, false, nil, {3400, 1317}, "Bring the head of Targorr to Guard Berton in Lakeshire.", "Targorr is inside the dungeon. He usually spawns in the first cell on the right or the second cell on the left of the central wing; rarely, in the northernmost cell between the two wings.", {{22,2}, {23,3}, {28,4}, {33,5}}, {3630}, nil, 859, "Guard Berton", { xp = 2000, rep = { {72, 100, "Stormwind City"} } } },
        { 387, "A", 22, 26, "Warden Thelwater", "Stormwind City - The Stockade 51,69", nil, false, nil, nil, "Take stock of the Stockade for Warden Thelwater of Stormwind: kill 10 Defias Convicts, 8 Defias Criminals and 8 Defias Insurgents.", "The quest is issued by the warden outside the dungeon.", {{22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 1719, "Warden Thelwater", { xp = 2650, money = 4000, rep = { {72, 150, "Stormwind City"} } } },
        { 388, "A", 22, 26, "Nikova Raskol", "Stormwind City - Old Town 75,63", nil, false, nil, nil, "Collect 10 Red Wool Bandanas and bring them to Nikova Raskol in Stormwind City.", "Nikova Raskov wanders around Old Town; nearly every enemy in the Stockade drops a mask.", {{22,2}, {24,3}, {29,4}, {34,5}}, {2909}, nil, 1721, "Nikova Raskol", { xp = 2650, money = 4000, rep = { {72, 150, "Stormwind City"} } } },
    },
    ["gnomeregan"] = {
        { 2843, "H", 20, 35, "Scooty", "Stranglethorn Vale - Booty Bay 27,77", "Gnomer-gooooone!", false, {2842}, {9173}, "Wait while Scooty fixes the goblin teleporter.", "The prerequisite is from Sovik (Orgrimmar - Valley of Honor 75,25). Completing it lets you use the Booty Bay teleporter. ◎ The goblin transponder can be discarded after use; if you lose it, just tell Scooty and you get another.", {{20,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7853, "Scooty", nil },
        { 2922, "A", 20, 26, "Tinkmaster Overspark", "Ironforge - Tinker Town 69,50", "Tinkmaster Overspark", false, {2923}, nil, "Bring the Storage Core of Techbot to Tinkmaster Overspark in Ironforge.", "The prerequisite can be taken from Brother Sarno (Stormwind City - Cathedral Square 51,48). Techbot is near the back door before entering the dungeon.", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {9277}, nil, 7944, "Tinkmaster Overspark", { xp = 2650, money = 2000, rep = { {54, 150, "Gnomeregan Exiles"} } } },
        { 2926, "A", 20, 27, "Ozzie Togglevolt", "Dun Morogh - Kharanos 45,49", "Gnogaine", false, {2927}, nil, "Use the Empty Lead Vial to collect Irradiated Dust from Irradiated Invaders or Irradiated Pillagers, fill it, and bring it to Ozzie Togglevolt in Kharanos.", "The prerequisite can be taken from Nogg (Ironforge - Tinker Town 69,50). Sampling method: use the Empty Lead Vial on a living Irradiated Invader/Pillager.", {{20,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {9284, 9283}, nil, 1268, "Ozzie Togglevolt", { xp = 2200, money = 2200, rep = { {54, 100, "Gnomeregan Exiles"} } } },
        { 2928, "A", 20, 30, "Shoni the Shilent", "Stormwind City - Dwarven District 63,34", nil, false, nil, {9608, 9609, 270045}, "Collect 24 Mechanical Gizzards and bring them to Shoni in Stormwind City.", "All the robots drop gizzards.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9309}, nil, 6579, "Shoni the Shilent", { xp = 2450, rep = { {72, 100, "Stormwind City"}, {54, 100, "Gnomeregan Exiles"} } } },
        { 2962, "A", 20, 30, "Ozzie Togglevolt", "Dun Morogh - Kharanos 45,49", "The Only Cure is More Green Glow", false, {2926}, nil, "Collect High-Efficiency Irradiated Dust in Gnomeregan (highly unstable, it decays quickly) and return the Heavy Lead Vial to Ozzie as well.", "Sampling method: use the Heavy Lead Vial on living Irradiated Oozes, Irradiated Creepers or Irradiated Water Elementals.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9365, 9364}, nil, 1268, "Ozzie Togglevolt", { xp = 2450, money = 2500 } },
        { 2904, nil, 24, 30, "Kernobee", "Gnomeregan", nil, true, nil, {9535, 9536, 270042}, "Escort Kernobee to the exit, then report back to Scooty in Booty Bay.", "Escort quest. Scooty is in Stranglethorn Vale - Booty Bay (27,77). The escort ends at the dungeon's FRONT entrance (deliver him to the door; no need to go through); the little gnome won't pull adds on his own, so stealth classes can do the whole quest while stealthed.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 7850, "Kernobee", { xp = 2450 } },
        { 2924, "A", 24, 30, "Klockmort Spannerspan", "Ironforge - Tinker Town 68,46", "Essential Artificials", false, {2925}, nil, "Collect 12 Basic Modules and bring them to Klockmort Spannerspan in Ironforge.", "The prerequisite can be taken from Mahir (Darnassus - Warriors' Terrace 59,45). All enemies in Gnomeregan can drop them.", {{24,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9278}, nil, 6169, "Klockmort Spannerspan", { xp = 3050, money = 5500, rep = { {54, 150, "Gnomeregan Exiles"} } } },
        { 2841, "H", 25, 35, "Nogg", "Orgrimmar - Valley of Honor 75,25", nil, false, nil, {9623, 9624, 9625}, "Retrieve the drilling rig blueprints and the combination to Mekgineer's Safe from Gnomeregan and bring them to Nogg in Orgrimmar.", "Mekgineer Thermaplugg is the final boss of Gnomeregan. During the fight, remember to press the button beside him to stop him throwing bombs.", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, {9153, 9299}, nil, 3412, "Nogg", { xp = 2750, rep = { {76, 100, "Orgrimmar"} } } },
        { 2929, "A", 25, 35, "High Tinker Mekkatorque", "Ironforge - Tinker Town 68,48", nil, false, nil, {9623, 9624, 9625}, "Enter Gnomeregan and kill Mekgineer Thermaplugg, then report to High Tinker Mekkatorque.", "He is the final boss. During the fight, press the button beside him to stop him throwing bombs.", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7937, "High Tinker Mekkatorque", { xp = 2750, money = 3500, rep = { {54, 100, "Gnomeregan Exiles"} } } },
        { 2930, "A", 25, 30, "Master Mechanic Castpipe", "Ironforge - Tinker Town 69,48", "Data Rescue", false, {2931}, {9605, 9604}, "Bring the Colorful Punch Cards to Master Mechanic Castpipe in Ironforge.", "The optional prerequisite is from Gaxim Rustfizzle (Stonetalon Mountains 59,67). Punch-card relay: the White Punch Card drops from the wandering elites on the upper level outside the instance; insert it into the card reader outside the instance, and each reader gives you the card for the next one — grab Techbot's brain along the way.", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9316}, nil, 7950, "Master Mechanic Castpipe", { xp = 3650, money = 2500, rep = { {54, 200, "Gnomeregan Exiles"} } } },
        { 2951, nil, 25, 30, "Super Cleaner 5200", "Gnomeregan - Clean Zone", nil, true, nil, nil, "Put grimy items into the Super Cleaner 5200, insert three silver coins to start the machine.", "This quest is repeatable with all \"grimy\" items.", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9308}, nil, nil, nil, { xp = 2450, money = 300 } },
        { 2952, nil, 25, 30, "Super Cleaner 5200", nil, nil, true, {2951}, {9363}, nil, nil, {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, nil, nil, { xp = 2450 } },
        { 2945, nil, 28, 34, "Return of the Ring", "Random drop in Gnomeregan", nil, false, nil, nil, "Figure out how to get the Grimy Ring cleaned.", "Just clean it with the Super Cleaner 5200 — the machine is inside the dungeon.", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9326}, nil, nil, nil, { xp = 2700, money = 300 } },
        { 2947, "A", 28, 34, "Return of the Ring", "Obtained by cleaning the Grimy Ring", "Return of the Ring", true, nil, nil, "You may keep the ring, or find its owner by the name engraved inside.", "Bring it to Talvash del Kissel (Ironforge - Mystic Ward 36,3). The reward ring's stats are random.", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9362}, nil, nil, nil, { xp = 2700 } },
        { 2949, "H", 28, 34, "Return of the Ring", "Obtained by cleaning the Grimy Ring", "Return of the Ring", true, {2945}, nil, "You may keep the ring, or find its owner by the name engraved inside.", "Bring it to Nogg (Orgrimmar - Valley of Honor 75,25). The reward ring's stats are random.", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9362}, nil, nil, nil, { xp = 2700 } },
    },
    ["razorfen_kraul"] = {
        { 1221, nil, 20, 26, "Mebok Mizzyrix", "The Barrens - Ratchet 62,37", nil, false, nil, {6755}, "Gather the Opened Chest, the Gopher Cane and the \"Gopher Command Manual\"; use the chest in Razorfen Kraul to summon the gopher and make it sniff out the Blueleaf Tubers; finally bring the cane, the chest and 10 Blueleaf Tubers to Mebok Mizzyrix in Ratchet.", "Both the chest and the manual can be found near Mebok Mizzyrix.", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {5876, 5880, 5897, 6684}, nil, 3446, "Mebok Mizzyrix", { xp = 2100, rep = { {470, 100, "Ratchet"} } } },
        { 1701, nil, 20, nil, "Furen Longbeard", "Stormwind City - Dwarven District 64,37", "Fire Hardened Mail", false, {1702}, nil, "Gather the specified materials for Frun Longbeard in Stormwind City.", "Warrior only! The phosphorus comes from Roogug; Scorched Spider Fangs from Wetlands spiders, and Charred and Sleek Chimera Horns from chimera cubs and females in Stonetalon Mountains. Roogug location: take the first left inside the dungeon, follow the curve over the vine bridge — he is right there on the other side.", {{20,1}, {24,2}, {26,3}, {31,4}, {36,5}}, {6838, 6839, 6840, 6841, 6842}, "Warrior", 5413, "Furen Longbeard", nil },
        { 1838, "H", 20, nil, "Thun'grim Firegaze", "The Barrens 57,30", "Brutal Armor", false, {1825}, nil, "Collect 15 Smoky Iron Ingots, 10 Azurite Powders, 10 Iron Bars and 1 vial of Phlogiston for Thorngrimr.", "Warrior only! Phlogiston comes from Rukhug. After turning in, he will offer the follow-up quest.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {7126, 7127, 3575, 6841, 7587}, "Warrior", 5878, "Thun'grim Firegaze", nil },
        { 1144, nil, 23, 30, "Willix the Importer", "Razorfen Kraul", nil, true, nil, {6748, 6750, 6749}, "Escort Willix the Importer out of Razorfen Kraul.", "The escort fails if you get too far ahead of him or fall too far behind. Turn right from the entrance through the boar area to reach Willix — no bosses need to be cleared.", {{22,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 4508, "Willix the Importer", { xp = 3050, rep = { {470, 150, "Ratchet"} } } },
        { 1142, "A", 25, 30, "Heralath Fallowbrook", "Razorfen Kraul", nil, true, nil, {6751, 6752}, "Retrieve Thalara's Pendant and return it to Thalara Fallowbrook in Darnassus.", "The pendant is a random drop. Turn-in location: Thalara Fallowbrook (Darnassus - Trade District 69,67).", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {5825}, nil, 4510, "Heralath Fallowbrook", { xp = 3050, rep = { {69, 150, "Darnassus"} } } },
        { 1101, "A", 29, 34, "Falfindel Waywarder", "Feralas - Sarannar 89,46", "The Crone of the Kraul", false, {1100}, {4197, 6742, 6725}, "Bring Calgar Spinegouge's badge to Falfindel Waywarder in Sarannar.", "The badge drops from Calgar Spinegouge.", {{29,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {5792}, nil, 4048, "Falfindel Waywarder", { xp = 3350 } },
        { 1102, "H", 29, 34, "Auld Stonespire", "Thunder Bluff 36,59", nil, false, nil, {4197, 6742, 6725}, "Bring Calgar Spinegouge's heart to Auld Stonespire in Thunder Bluff.", "Calgar Spinegouge is inside the dungeon.", {{29,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {5793}, nil, 4451, "Auld Stonespire", { xp = 4050, rep = { {81, 200, "Thunder Bluff"} } } },
        { 1109, "H", 30, 33, "Master Apothecary Faranell", "Undercity - The Apothecarium 48,69", nil, false, nil, nil, "Collect a sample of Marsh Bat guano for Master Apothecary Faranell of the Undercity.", "Only the Kraul Bats in the far-west chamber (just before the last boss, Charlga Razorflank) drop the guano — with a very high drop rate — and you must fight through most of the dungeon to reach them.", {{30,2}, {31,3}, {36,4}, {42,5}}, {5801}, nil, 2055, "Master Apothecary Faranell", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
