    ["razorfen_downs"] = {
        { 6521, "H", 28, 36, "Varimathras", "Undercity - Royal Quarter 56,92", "An Unholy Alliance", false, {6522}, {17039, 17042, 17043}, "Bring Ambassador Marquin's head to Varimathras in the Undercity.", "The prerequisite is given by Razorfen Kraul's final boss. Ambassador Malcin stands in the open ground before the dungeon entrance (The Barrens - Razorfen Downs 48,92).", {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17009}, nil, 2425, "Varimathras", { xp = 3500, money = 2000 } },
        { 6522, "H", 28, 36, "Starts from the item [Small Scroll]", nil, nil, false, nil, nil, nil, nil, {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17008}, nil, nil, nil, { xp = 2800, money = 4000 } },
        { 6626, nil, 28, 35, "Myriam Moonsinger", "The Barrens - Razorfen Downs 49,94", nil, false, nil, nil, "Kill 8 Razorfen Guardians, 8 Razorfen Weavers and 8 Death Cultists, then report to Myriam Moonsinger at the Razorfen Downs entrance.", "All three of these mobs are on the path you take before entering the dungeon.", {{28,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 12866, "Myriam Moonsinger", { xp = 3450, money = 7500 } },
        { 3523, nil, 32, 37, "Belnistrasz", nil, nil, true, nil, nil, nil, "This is not the escort quest itself — complete this one first, and only then the real escort quest 'Extinguishing the Idol' becomes available. Make sure EVERYONE in the party finishes this quest before starting the escort segment, or those who haven't will miss the follow-up.", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, {10682}, nil, 8516, "Belnistrasz", { xp = 285 } },
        { 3525, nil, 32, 37, "Belnistrasz", "Razorfen Downs", "Extinguishing the Idol", true, {3523}, {10710}, "Accompany Belnistrasz to the quillboar idol in Razorfen Downs and protect him while his ritual seals it.", "Once you agree to help, waves of mobs will attack him throughout the ritual — keep him alive; when it is done, turn the quest in at the idol for the reward.", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, nil, nil, 8516, "Belnistrasz", { xp = 4250 } },
        { 3341, "H", 37, 42, "Andrew Brownell", "Undercity - Magic Quarter 72,32", nil, false, nil, {10823, 10824}, "Kill Amnennar the Coldbringer for Andrew Brownell and bring back his skull.", "Amnennar the Coldbringer is the final boss of Razorfen Downs.", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {10420}, nil, 2308, "Andrew Brownell", { xp = 4300, rep = { {68, 150, "Undercity"} } } },
        { 3636, "A", 39, 42, "Archbishop Benedictus", "Stormwind City - Cathedral of Light 50,45", nil, false, nil, {10823, 10824}, "Kill Amnennar the Coldbringer of Razorfen Downs for Archbishop Benedictus.", "He is the final boss of Razorfen Downs. ★ This quest cannot be shared — everyone in the party must pick it up for themselves.", {{39,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 1284, "Archbishop Benedictus", { xp = 4300, rep = { {72, 150, "Stormwind City"} } } },
