        { 1360, "A", 33, 43, "Krom Stoutarm", "Ironforge - Hall of Explorers 74,9", nil, false, nil, nil, "Find Krom Stoutarm's Chest in the northern hall of Uldaman, take the treasure inside, and bring it back to him in Ironforge.", "The treasure is in the cave before the dungeon, at the end of the first passage to the southeast in the north.", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8027}, nil, 6294, "Krom Stoutarm", { xp = 3600, money = 6000, rep = { {47, 100, "Ironforge"} } } },
        { 2342, "H", 33, 43, "Patrick Garrett", "Undercity 72,48", nil, false, nil, nil, "Recover Garrett's family treasure from the chest in the southern hall of Uldaman and bring it to Patrick Garrett in the Undercity.", "The treasure can be reached before entering the dungeon, at the end of the southern passage.", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8026}, nil, 5651, "Patrick Garrett", { xp = 3600, money = 6000, rep = { {68, 100, "Undercity"} } } },
        { 721, nil, 35, nil, "Prospector Ryedol", "Badlands 53,43", "Amulet of Secrets", false, {720}, nil, "Enter Uldaman and find Hammertoe Grez.", "The chain starts with a crumpled map (Badlands 53,33). Hammertoe Grez is near the dungeon entrance.", {{35,3}, {38,4}, {44,5}}, nil, nil, 2910, "Prospector Ryedol", nil },
        { 722, "A", 35, 40, "Hammertoe Grez", "Uldaman (dungeon-entrance map).", "Amulet of Secrets", false, {721}, nil, "Retrieve Hammertoe's amulet and bring it to Hammertoe Grez in Uldaman.", "The amulet drops from Magregan Deepshadow.", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {4635}, nil, 2909, "Hammertoe Grez", { xp = 3150, rep = { {47, 100, "Ironforge"} } } },
        { 1139, "A", 35, 45, "Advisor Belgrum", "Ironforge - Hall of Explorers 77,10", "The Lost Tablets of Will", false, {762}, {6723}, "Find the Tablet of Resolve and bring it to Advisor Belgrum in Ironforge.", "The tablet is inside the dungeon, right beside Galgann Firehammer.", {{35,1}, {41,2}, {43,3}, {48,4}, {55,5}}, {5824}, nil, 2918, "Advisor Belgrum", { xp = 5850, money = 13000, rep = { {47, 200, "Ironforge"} } } },
        { 1956, nil, 35, nil, "Tabetha", "Dustwallow Marsh 46,57", "Exorcism", false, {1955}, nil, "Find an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", "Mage only! The power source drops from the Obsidian Sentinel. The sentinel is right inside the back door — enter from the Badlands back entrance (67,44) and it is the first thing you see, with no guarding adds.", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {8053}, "Mage", 6546, "Tabetha", nil },
        { 2240, "A", 35, 40, "Baelog", "Uldaman", "The Hidden Chamber", true, {2398}, {9626, 9627}, "Read Baelog's diary, uncover the hidden chamber, then report back to Prospector Tabor Stormpike in Ironforge.", "The Hidden Chamber is inside the instance. Opening procedure: get the Shaft of Tsol from Revelosh and the Gni'kiv Medallion from Baelog's chest, combine them into the Staff of Prehistoria; then use it in the Map Room between the two halls to summon Ironaya — defeat her and enter the Hidden Chamber.", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 6906, "Baelog", { xp = 3900, rep = { {47, 150, "Ironforge"} } } },
        { 2398, nil, 35, nil, "Prospector Stormpike", "Ironforge - Hall of Explorers 75,12", nil, false, nil, nil, "Find Baelog inside Uldaman.", "Ballog is inside the dungeon. Breadcrumb quest: it cannot be completed if you have already accepted or completed 'The Hidden Chamber'.", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 1356, "Prospector Stormpike", nil },
        { 17, "A", 36, 42, "Ghak Healtouch", "Loch Modan - Thelsamar 37,49", "Uldaman Reagent Run", false, {2500}, {9030}, "Collect 12 Purple Lotuses and bring them back to Ghak Healtouch in Thelsamar.", "The Magenta Fungus Caps are scattered in the cave BEFORE the instance (not inside), mostly by campfires and behind tents; with Herbalism tracking on they show up on the minimap. Each step also grants 250 Ironforge reputation. The prerequisite quest is taken from the same NPC.", {{38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 1470, "Ghak Healtouch", { xp = 3450, money = 5500, rep = { {47, 100, "Ironforge"} } } },
        { 2202, "H", 36, 42, "Jarkal Mossmeld", "Badlands - Kargath 2,69", "Uldaman Reagent Run", false, {2258}, {9030}, "Collect 12 Purple Lotuses and bring them to Jarkal Mossmeld in Kargath.", "The prerequisite is also taken from Jarkal Mossmeld. The mushrooms are scattered throughout the dungeon; Find Herbs marks them on the minimap.", {{36,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 6868, "Jarkal Mossmeld", { xp = 3450, money = 5500, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 2198, "A", 37, 41, "The Shattered Necklace", "Random drop inside Uldaman", nil, false, nil, nil, "Find out the history of the Broken Necklace and assess its value.", "Bring the necklace to Talvash del Kissel in Ironforge (Ironforge - Mystic Ward 36,3).", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, nil, nil, { xp = 3300 } },
        { 2199, "A", 37, 41, "Talvash del Kissel", "Dun Morogh", nil, false, {2198}, nil, nil, nil, {{37,2}, {39,3}, {44,4}, {51,5}}, {2842}, nil, 6826, "Talvash del Kissel", { xp = 2450, rep = { {54, 75, "Gnomeregan Exiles"} } } },
        { 2200, nil, 37, nil, "Talvash del Kissel", "Ironforge - Mystic Ward 36,3", "Back to Uldaman", false, {2199}, nil, "Search Uldaman for Talvash's magic necklace — a dead paladin was its last holder.", "The paladin is inside the dungeon: the body is in the northwest corner of the Hall of the Keepers (the first sideways-'8' shaped area), marked with a yellow '?' — no searching required.", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7667}, nil, 6826, "Talvash del Kissel", nil },
        { 2204, "A", 37, 44, "Talvash's Divining Bowl", "Talvash's Divining Bowl", "Restoring the Necklace", true, {2201}, nil, "Take the power source from the strongest stone golem of Uldaman and bring it to Talvash in Ironforge.", "The necklace's power source drops from Archaedas.", {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7672}, nil, nil, nil, { xp = 930 } },
        { 2283, "H", 37, 41, "Dran Droffers", "Orgrimmar - Rogue Quarter 59,36", nil, false, nil, nil, "Look for a valuable necklace (possibly damaged) at the Uldaman excavation and bring it to Dran Droffers in Orgrimmar.", "The necklace is a random drop inside the dungeon.", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, 6986, "Dran Droffers", { xp = 2450, rep = { {76, 75, "Orgrimmar"} } } },
        { 2284, "H", 37, nil, "Dran Droffers", "Orgrimmar - Rogue Quarter 59,36", "Necklace Recovery, Take 2", false, {2283}, nil, "Search Uldaman for clues about the gems.", "The paladin is inside the dungeon: enter and keep hugging the wall on your right — it leads straight to the body.", {{37,2}, {39,3}, {44,4}, {51,5}}, nil, nil, 6986, "Dran Droffers", nil },
        { 2318, "H", 37, nil, "Remains of a Paladin", "Uldaman", "Translating the Journal", false, {2284}, nil, "Find someone at Kargath Outpost in the Badlands who can translate the paladin's journal.", "The person is Jarkal Mossmeld (Badlands - Kargath 2,46); lending him the necklace completes the translation.", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7886}, nil, 6912, "Remains of a Paladin", nil },
        { 2338, "H", 37, 42, "Jarkal Mossmeld", "Badlands", "Find the Gems and Power Source", false, {2318}, nil, nil, nil, {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7886}, nil, 6868, "Jarkal Mossmeld", { xp = 345, rep = { {530, 10, "Darkspear Trolls"} } } },
        { 2339, "H", 37, 44, "Jarkal Mossmeld", "Badlands - Kargath 2,46", "Find the Gems and Power Source", false, {2338}, nil, "Retrieve the necklace's ruby, topaz, sapphire and power source from Uldaman and bring them to Jarkal Mossmeld in Kargath. The ruby is in the Dark Iron defense area, the topaz in an urn in the trogg area, the sapphire held by the trogg leader Grimlok, and the power source on the strongest creature of Uldaman.", "Gem locations: Conspicuous Urn, Shadowforge Vault, Grimlok. Opening the Shadowforge Vault spawns mobs — be careful.", {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7669, 7670, 7671, 7672, 7668}, nil, 6868, "Jarkal Mossmeld", { xp = 3750, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 2340, "H", 37, 44, "Jarkal Mossmeld", "Badlands", nil, false, nil, nil, nil, nil, {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7887}, nil, 6868, "Jarkal Mossmeld", { xp = 1850, money = 12500, rep = { {76, 50, "Orgrimmar"} } } },
        { 2361, "A", 37, 44, "Talvash del Kissel", "Dun Morogh", nil, false, {2204}, {7673}, nil, nil, {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, nil, nil, 6826, "Talvash del Kissel", { xp = 5600, rep = { {54, 200, "Gnomeregan Exiles"} } } },
        { 2201, "A", 40, 43, "Remains of a Paladin", "Uldaman", "Find the Gems", true, {2200}, nil, "Find out where the ruby, sapphire and topaz are in Uldaman, then report back to Talvash using the divining vial he gave you.", "The gems are respectively in the Conspicuous Urn and the Shadowforge Vault inside the dungeon, and on Grimlok. Note: opening the Shadowforge Vault spawns mobs.", {{37,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {7669, 7670, 7671, 7668}, nil, 6912, "Remains of a Paladin", { xp = 3600 } },
        { 2278, nil, 40, nil, "The Discs of Norgannon", "Uldaman", nil, false, nil, nil, "Learn ancient knowledge from the Stone Watcher, then activate the Norgannon Disc; bring the Miniaturized Disc of Norgannon back to the Explorer's League in Ironforge.", "After taking the quest, first talk to the disc next to the Stone Watcher, then use the Platinum Disc to obtain the miniature version and hand it to High Explorer Magellas (Ironforge - Hall of Explorers 69,18). Follow-up quests are taken from the NPCs nearby.", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, nil, nil, nil, nil, nil },
        { 2279, "A", 40, 47, "The Discs of Norgannon", nil, "The Platinum Disc", true, nil, nil, nil, nil, {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {6064}, nil, nil, nil, { xp = 5250, rep = { {47, 150, "Ironforge"} } } },
        { 2280, "H", 40, 47, "The Discs of Norgannon", nil, "The Platinum Disc", true, {2278}, nil, nil, "After killing Archaedas, walk into the vault behind him and click the disc on the pedestal to accept the quest; after listening to the summoned ghost's full story, click the disc AGAIN to receive the miniature — miss this step and you have to run the dungeon again. Turn in at Thunder Bluff (NPC around 35,47).", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {6064}, nil, nil, nil, { xp = 5250, rep = { {81, 150, "Thunder Bluff"} } } },
        { 2341, "H", 40, 44, "Dran Droffers", "Orgrimmar", nil, false, {2340}, {7888}, nil, nil, {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, nil, nil, 6986, "Dran Droffers", { xp = 5600, rep = { {530, 100, "Darkspear Trolls"} } } },
    },
    ["zul_farrak"] = {
        { 2768, nil, 40, 47, "Bilgewhizzle", "Tanaris - Gadgetzan 52,28", nil, false, nil, {9533, 9534}, "Bring the Dowsing Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", "The Dowsing Rod comes from Sergeant Bly. You must first finish the gauntlet event in the temple and defeat Sergeant Bly to get it.", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {8548}, nil, 7407, "Chief Engineer Bilgewhizzle", { xp = 6300, rep = { {369, 200, "Gadgetzan"} } } },
        { 2770, nil, 40, 50, "Wizzle Brassbolts", "Thousand Needles - Shimmering Flats 78,77", nil, false, {2769}, {11122}, "Bring Gahz'rilla's scale to Wizzle Brassbolts on the Shimmering Flats.", "The prerequisite can be taken from Klockmort Spannerspan (Ironforge - Tinker Town 68,46), but it is optional. Ring the gong in the dungeon's arena to summon Gahz'rilla — the Forever server no longer requires the Mallet of Zul'Farrak.", {{40,1}, {46,2}, {48,3}, {53,4}, {61,5}}, {8707}, nil, 4453, "Wizzle Brassbolts", { xp = 7100, money = 7500 } },
        { 2846, nil, 40, 46, "Tabetha", "Dustwallow Marsh 46,57", nil, false, {2861}, {9527, 9531}, "Bring the Crown of the Deeps to Tabetha in Dustwallow Marsh.", "The prerequisite comes from Bink (Ironforge 25,8). The crown drops from Hydromancer Velratha.", {{40,1}, {42,2}, {44,3}, {49,4}, {56,5}}, {9234}, nil, 6546, "Tabetha", { xp = 6050, money = 6500 } },
        { 2865, nil, 40, 45, "Tran'rek", "Tanaris - Gadgetzan 51,26", "Tran'rek", false, {2864}, nil, "Bring 5 intact Scarab Shells to Tran'rek in Gadgetzan.", "The optional prerequisite starts with Krazek (Stranglethorn Vale - Booty Bay 25,77) — not required, the quest can be taken directly. Every scarab drops a shell; the scarab hall has the densest concentration.", {{40,1}, {41,2}, {43,3}, {48,4}, {55,5}}, {9238}, nil, 7876, "Tran'rek", { xp = 3900, money = 6500, rep = { {369, 100, "Gadgetzan"} } } },
        { 2936, "H", 40, nil, "Master Gadrin", "Durotar - Sen'jin Village 55,74", "The Spider God", false, {2935}, nil, "Read the Seca Stone Tablet to learn the name of the spider god of the Witherbark trolls, then report back to Master Gadrin.", "The chain begins with the Vial series from the troll village in the Hinterlands. The tablet is inside the dungeon. Stealth classes can sneak straight to the tablet and finish reading it without fighting Theka the Martyr; the scarabs are neutral — just avoid AOE.", {{40,1}, {41,2}, {43,3}, {48,4}, {55,5}}, nil, nil, 3188, "Master Gadrin", nil },
        { 2991, "A", 40, 47, "Thadius Grimshade", "Blasted Lands - Nethergarde Keep 66,19", "Thadius Grimshade", false, {2990}, nil, "Bring Nekrum's medallion to Thadius Grimshade in the Blasted Lands.", "The chain starts with the gryphon master at Aerie Peak, Hinterlands (9,44). Nekrum is inside the dungeon: he spawns in the final wave that comes up the great stairs after Bly is freed.", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {9471}, nil, 8022, "Thadius Grimshade", { xp = 5250, money = 7000, rep = { {471, 150, "[UNUSED] Brother Milius"}, {47, 150, "Ironforge"} } } },
        { 3042, nil, 40, 45, "Trenton Lighthammer", "Tanaris - Gadgetzan 51,28", nil, false, nil, nil, "Collect 20 bottles of Troll Temper and bring them to Trenton Lighthammer in Gadgetzan.", "All the trolls can drop the temper.", {{40,1}, {41,2}, {43,3}, {48,4}, {55,5}}, {9523}, nil, 7804, "Trenton Lighthammer", { xp = 3900, money = 19500 } },
        { 3527, nil, 40, 47, "Yeh'kinya", "Tanaris - Steamwheedle Port 66,22", "The Prophecy of Mosh'aru", false, {3520}, nil, "Bring the first and second Mosh'aru Tablets to Yeh'kinya in Tanaris.", "The prerequisite is also taken from Yeh'kinya. The tablets drop from Martyr Seka and Hydromancer Velratha respectively.", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {10660, 10661}, nil, 8579, "Yeh'kinya", { xp = 5250 } },
    },
    ["maraudon"] = {
        { 7068, "H", 38, 42, "Uthel'nay", "Orgrimmar - Valley of Spirits 39,86", nil, false, nil, {17772, 17773}, "Collect 10 Shadow Shards from Maraudon and bring them to Uthel'nay in Orgrimmar.", "The shards come from the Shadow Shard Prowlers and Shadow Shard Splitters outside the dungeon.", {{39,2}, {40,3}, {45,4}, {52,5}}, {17756}, nil, 7311, "Uthel'nay", { xp = 3450, rep = { {530, 150, "Darkspear Trolls"} } } },
        { 7070, "A", 38, 42, "Archmage Tervosh", "Dustwallow Marsh - Theramore Isle 66,49", nil, false, nil, {17772, 17773}, "Collect 10 Shadow Shards from Maraudon and bring them to Archmage Tervosh on Theramore Isle in Dustwallow Marsh.", "The shards come from the Shadow Shard Prowlers and Shadow Shard Splitters outside the dungeon.", {{39,2}, {40,3}, {45,4}, {52,5}}, {17756}, nil, 4967, "Archmage Tervosh", { xp = 3450, rep = { {72, 150, "Stormwind City"} } } },
        { 7067, nil, 39, 48, "Centaur Pariah", "Desolace 45,86", nil, false, nil, {17774}, "Read \"The Pariah's Instructions\", retrieve the Uniting Charm from Maraudon, and bring it to the Centaur Pariah in southern Desolace.", "'The Pariah's Instructions' mentions the 5 khans. The Nameless Prophet drops the Amulet of Spirits, which is used to materialize the 5 khans.", {{39,1}, {44,2}, {46,3}, {51,4}, {58,5}}, {17758, 17781}, nil, 13717, "Centaur Pariah", { xp = 5450, money = 14000 } },
        { 7028, nil, 41, 47, "Willow", "Desolace 62,39", nil, false, nil, {17775, 17776, 17777, 17779}, "Collect 25 Theradras Crystal Statues for Willow of Desolace.", "Most enemies in Maraudon drop the figurine; the Nameless Prophet has the best drop rate and respawns nearby almost immediately after dying — great for fast farming.", {{41,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {17684}, nil, 13656, "Willow", { xp = 5250 } },
        { 7029, "H", 41, 47, "Vark Battlescar", "Desolace - Shadowprey Village 23,70", nil, false, nil, {17768, 17778, 17770}, "Fill the Azure Vial at the orange crystal pools of Maraudon and pour it on the Vile Stem vines to draw out the Corrupted Noxxion Scions; heal 8 plants and kill the scion, then report back to Vark Battlescar in Shadowprey Village.", "Fill the vial at the big outdoor pool with orange crystals (not the small pool the dryad stands in); the vines are in the orange area — use the vial next to a flower to summon a flower and an elemental; kill both and the completion is shared by the whole group.", {{41,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {17696, 17693}, nil, 11823, "Vark Battlescar", { xp = 5250 } },
        { 7041, "A", 41, 47, "Talendria", "Desolace - Nijel's Point 68,8", nil, false, nil, {17768, 17778, 17770}, "Fill the Azure Vial at the orange crystal pools of Maraudon and pour it on the Vile Stem vines to draw out the Corrupted Noxxion Scions; heal 8 plants and kill the scion, then report back to Talendria at Nijel's Point.", "Fill the vial at the big outdoor pool with orange crystals (not the small pool the dryad stands in); the vines are in the orange area — use the vial next to a flower to summon a flower and an elemental; kill both and the completion is shared by the whole group.", {{41,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {17696, 17693}, nil, 11715, "Talendria", { xp = 5250 } },
        { 7044, nil, 41, 49, "Cavindra", "Desolace - Maraudon dungeon entrance map", nil, false, nil, nil, "Recover the two parts of the Scepter of Celebras — Celebras's Wand and the Celebras Diamond — then find a way to speak with Celebras.", "Cavindra is right at the start of the orange area before the dungeon. The wand comes from Noxxion, the diamond from Vel'tarn. Celebras is inside the dungeon — you must defeat him before you can speak with him.", {{41,1}, {45,2}, {47,3}, {52,4}, {59,5}}, {17703, 17702}, nil, 13697, "Cavindra", { xp = 3400 } },
        { 7046, nil, 41, 49, "Celebras the Redeemed", "Maraudon", "The Scepter of Celebras", true, {7044}, {17191}, "Help Celebras the Redeemed craft the Scepter of Celebras; talk with him once more after the ritual is complete.", "The scepter is crafted by Celebras himself; talk to him after the ritual. If you lose the scepter, kill Celebras again and choose 'I lost my scepter' in the dialog to get another.", {{41,1}, {45,2}, {47,3}, {52,4}, {59,5}}, nil, nil, 13716, "Celebras the Redeemed", { xp = 5700 } },
        { 7064, "H", 45, 51, "Selendra", "Desolace - Shadowprey Village 27,77", nil, false, nil, {17705, 17743, 17753}, "Kill Princess Theradras, then report back to Selendra near Shadowprey Village in Desolace.", "Princess Theradras is inside the dungeon.", {{45,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 13699, "Selendra", { xp = 6100, rep = { {609, 150, "[UNUSED] Brother Milius"} } } },
        { 7065, "A", 45, 51, "Keeper Marandis", "Desolace - Nijel's Point 63,10", nil, false, nil, {17705, 17743, 17753}, "Kill Princess Theradras, then report back to Keeper Marandis at Nijel's Point in Desolace.", "Princess Theradras is inside the dungeon.", {{45,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 13698, "Keeper Marandis", { xp = 6100, rep = { {609, 150, "[UNUSED] Brother Milius"} } } },
        { 7066, nil, 45, 51, "Zaetar's Spirit", "Maraudon", "Seed of Life", true, {"Seed of Life"}, nil, "Find Remulos in Moonglade and give him the Seed of Life.", "Zaetar's spirit appears after the princess is killed. Remulos is at Moonglade - Temple of Remulos (36,41).", {{39,1}, {47,2}, {49,3}, {54,4}, {62,5}}, {17760}, nil, 12238, "Zaetar's Spirit", { xp = 6100, money = 15000, rep = { {609, 150, "[UNUSED] Brother Milius"} } } },
    },
    ["sunken_temple"] = {
        { 1445, "H", 38, 50, "Fel'zerul", "Swamp of Sorrows - Stonard 47,54", "The Temple of Atal'Hakkar", false, {1444}, {1490}, "Collect 20 Hakkari idols and bring them to Fel'zerul in Stonard.", "All enemies inside the temple drop the idols.", {{38,1}, {46,2}, {48,3}, {53,4}, {61,5}}, {6181}, nil, 1443, "Fel'zerul", { xp = 5900, rep = { {76, 150, "Orgrimmar"} } } },
        { 1446, nil, 38, 53, "Atal'ai Exile", "The Hinterlands 33,75", nil, false, nil, {11123, 11124}, "Bring back the head of Jammal'an and give it to the Atal'ai Exile in the Hinterlands.", "Jammal'an is inside the dungeon. You must first clear the ring of ghosts on the balconies (the undead trolls holding his barrier) before he can be engaged.", {{38,1}, {49,2}, {51,3}, {56,4}, {64,5}}, {6212}, nil, 5598, "Atal'ai Exile", { xp = 6550 } },
        { 3528, nil, 40, 53, "Yeh'kinya", "Tanaris - Steamwheedle Port 66,22", "The God Hakkar", false, {4787}, {10749, 10750, 10751}, "Bring the filled Hakkar egg to Yeh'kinya in Tanaris.", "The chain starts with \"The Souls of the Screechers\" (taken at this same dungeon). Use the Hakkar egg at the altar inside the dungeon to trigger the event; some of the spawned enemies drop Hakkari Blood — use it to douse the Eternal Flames. When all are out, the Avatar of Hakkar descends.", {{40,1}, {49,2}, {51,3}, {56,4}, {64,5}}, {10662, 10465}, nil, 8579, "Yeh'kinya", { xp = 7900, money = 24000 } },
        { 1475, "A", 41, 50, "Brohann Caskbelly", "Stormwind City - Dwarven District 69,40", "Into The Temple of Atal'Hakkar", false, {1469}, {1490}, "Collect 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind City.", "Take the prerequisite here. The tablets can all be looted BEFORE the instance: 1 underwater in the center of the entrance hall and 1 on each of the two side tables, respawning about every 8 minutes — wait a bit and even a full group gets theirs.", {{38,1}, {46,2}, {48,3}, {53,4}, {61,5}}, {6288}, nil, 5384, "Brohann Caskbelly", { xp = 7100, rep = { {47, 200, "Ironforge"} } } },
        { 3380, "H", 46, nil, "Witch Doctor Uzer'i", "Feralas 74,43", nil, false, nil, nil, "Find Marvon Rivetseeker in Tanaris.", "Location 52,45.", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 8115, "Witch Doctor Uzer'i", nil },
        { 3445, nil, 46, nil, "Angelas Moonbreeze", "Feralas - Feathermoon Stronghold 31,45", nil, false, nil, nil, "Find Marvon Rivetseeker in Tanaris.", "Location 52,45.", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 7900, "Angelas Moonbreeze", nil },
        { 3446, nil, 46, 51, "Marvon Rivetseeker", "Tanaris 52,45", "Into the Depths", false, {3444}, nil, "Enter the Sunken Temple in the Swamp of Sorrows and find the Altar of Hakkar.", "The altar is on the map. Inside the dungeon take the right-hand stairs down into the 'Pit of Refuse' — the Altar of Hakkar is right there.", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, {10466}, nil, 7771, "Marvon Rivetseeker", { xp = 4900 } },
        { 3447, nil, 46, 51, "Marvon Rivetseeker", "Tanaris 52,45", "Secret of the Circle", false, {3446}, {10773}, "Enter the Sunken Temple and solve the hidden secret of the statue cluster.", "The statues are inside the dungeon; activate them in this order: South → North → Southwest → Southeast → Northwest → Northeast.", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 7771, "Marvon Rivetseeker", { xp = 6100 } },
        { 4143, nil, 47, nil, "Gregan Brewspewer", "Feralas 45,25", "Haze of Evil", false, {4142}, nil, "Collect 5 Atal'ai Mists and report back to Mugen in Un'Goro Crater.", "The prerequisite 'Muigin and Larion' starts with Muigin (Un'Goro Crater - Marshal's Refuge 42,9). Temple deep lurkers, dark crawlers and fused oozes all drop it. You MUST go inside the instance — the oozes outside don't drop it. Take the right-hand stairs down inside the entrance to reach the lurker/ooze area.", {{47,1}, {48,2}, {50,3}, {55,4}, {63,5}}, {11318}, nil, 7775, "Gregan Brewspewer", nil },
        { 4146, "H", 47, 52, "Liv Rizzlefix", "The Barrens 62,38", "Zapper Fuel", false, {4147}, nil, "Collect 5 Atal'ai Mists and deliver them to Larion at Marshall's Refuge.", "The prerequisite 'Larion and Muigin' starts with Larion (Un'Goro Crater 45,8). Temple deep lurkers, dark crawlers and oozes all drop it. You MUST go inside the instance — the oozes outside don't drop it. Take the right-hand stairs down inside the entrance to reach the lurker/ooze area.", {{47,1}, {48,2}, {50,3}, {55,4}, {63,5}}, {11319, 11318}, nil, 8496, "Liv Rizzlefix", { xp = 5100 } },
        { 3373, nil, 48, 55, nil, "The Essence of Eranikus drops from (the Shade of Eranikus)", nil, false, nil, {10455}, "Place the Essence of Eranikus into the Essence Font beside his lair in the Sunken Temple.", "The essence drops from the Shade of Eranikus; the Essence Font is right beside him.", {{48,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {10454}, nil, nil, nil, { xp = 2800 } },
        { 8232, nil, 50, nil, "Ogtinc", "Azshara 42,43", "The Green Drake", false, {8231}, nil, "Bring the tooth of Morphras to Ointink of Azshara — he lives on the cliff top northeast of the Edalas ruins.", "Hunter class quest. Morphras is inside the dungeon.", {{50,3}, {55,4}, {63,5}}, {20019}, "Hunter", 8405, "Ogtinc", nil },
        { 8236, nil, 50, nil, "Archmage Xylem", "Azshara 29,40", "The Azure Key", false, {8235}, nil, "Bring the Cerulean Key to Duke Jorach Ravenholdt.", "Rogue class quest. The key drops from Morphras. Duke Jorach Ravenholdt is at Alterac Valley - Ravenholdt Manor (86,79).", {{50,3}, {55,4}, {63,5}}, {20022}, "Rogue", 8379, "Archmage Xylem", nil },
        { 8253, nil, 50, nil, "Archmage Xylem, Morphras", "Azshara 29,40", "Destroy Morphaz", false, {8252}, nil, "Retrieve the Arcane Shard from Morphras and report back to Archmage Xylem.", "Mage class quest. Morphras is inside the dungeon.", {{50,3}, {55,4}, {63,5}}, {20085}, "Mage", 8379, "Archmage Xylem", nil },
        { 8257, nil, 50, nil, "Ogtinc", "Azshara 42,43", "Blood of Morphaz", false, {8256}, nil, "Go to the Sunken Temple of Atal'Hakkar, kill the green dragon Morphras, and bring his blood to Greta Mosshoof in Felwood.", "Priest class quest. Morphras is inside the dungeon. Greta Mosshoof is at Felwood - Emerald Sanctuary (51,82).", {{50,3}, {55,4}, {63,5}}, {20025}, "Priest", 8405, "Ogtinc", nil },
        { 8413, "H", 50, nil, "Bath'rah the Windwatcher", "Alterac Mountains 80,67", "Da Voodoo", false, {8412}, nil, "Bring the Voodoo Feathers to Basha Windcaller.", "Shaman class quest. Each of the 6 lesser trolls drops one.", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "Shaman", 6176, "Bath'rah the Windwatcher", nil },
        { 8418, nil, 50, nil, "Ashlam Valorfist", "Western Plaguelands - Chillwind Camp 43,85", "Forging the Mightstone", false, {8416}, nil, "Bring the Voodoo Feathers to Ashlam Valorfist.", "Paladin class quest. Each of the 6 lesser trolls drops one.", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "Paladin", 10838, "Commander Ashlam Valorfist", nil },
        { 8422, nil, 50, nil, "Impsy", "Felwood 42,45", "Trolls of a Feather", false, {8421}, nil, "Collect 6 Voodoo Feathers from the trolls in the Sunken Temple.", "Warlock class quest. Each of the 6 lesser trolls drops one.", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "Warlock", 14470, "Impsy", nil },
        { 8425, nil, 50, nil, "Fallen Hero of the Horde", "Dustwallow Marsh 34,66", "Voodoo Feathers", false, {8424}, nil, "Bring the Voodoo Feathers taken from the trolls of the Sunken Temple to the Spirit of the Fallen Hero.", "Warrior class quest. The 6 little trolls are the undead trolls holding Jammal'an's barrier — up the stairs and turn right as you enter (not the spiral staircase).", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "Warrior", 7572, "Fallen Hero of the Horde", nil },
        { 9053, nil, 50, nil, "Torwa Pathfinder", "Un'Goro Crater 72,76", "A Better Ingredient", false, {9051}, nil, "Take some Rotting Vines from the guards at the bottom of the Sunken Temple and bring them to Torwa Pathfinder.", "Druid class quest. The vines drop from the summoned Atal'alarion; you must first solve the statue puzzle correctly. Statue order by minimap clock: 6 → 12 → 8 → 4 → 10 → 2 (correct hits light the statues green).", {{50,3}, {55,4}, {63,5}}, {22444}, "Druid", 9619, "Torwa Pathfinder", nil },
    },
    ["blackrock_depths"] = {
        { 4083, nil, 40, 55, "Senani Thunderheart", "Blackrock Depths", nil, true, nil, nil, "Senani Thunderheart of the Chalice of Spirits wants you to gather the materials he needs.", "Requires Mining 230 to take; after completing it you learn Smelt Dark Iron. Materials: 2 [Star Rubies], 20 [Gold Bars], 10 [Truesilver Bars]. Afterwards bring [Dark Iron Ore] to the Black Forge to smelt it.", {{40,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {7910, 3577, 6037}, nil, nil, nil, { xp = 5650 } },
        { 3802, nil, 48, 52, "Franclorn Forgewright", "Blackrock Mountain dungeon entrance map", "Dark Iron Legacy", false, {3801}, {11000}, "Kill Vornus Darkvale to reclaim the warhammer \"Ironheart\", then place the Hammer of Ironheart on the statue of Franclorn Forgewright in the Thaurissan shrine.", "Franclorn Forgewright is at the center of Blackrock Mountain, above his own tomb — you must first die and become a ghost to talk to him; talk twice to activate the quest. Vornus Darkvale is inside the instance, and so is the shrine.", {{48,2}, {50,3}, {55,4}, {63,5}}, {10999}, nil, 8888, "Franclorn Forgewright", { xp = 5100, money = 23000 } },
        { 3906, "H", 48, nil, "Thunderheart", "Badlands - Kargath 3,48", nil, false, nil, nil, "Kill Overlord Pyron at the quarry of Blackrock Mountain, then report back to Thunderheart.", "Pyron is a fire elemental elite just outside the dungeon entrance.", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, 9084, "Thunderheart", nil },
        { 3907, "H", 48, 56, "Thunderheart", "Badlands - Kargath 3,48", "The Last Element", false, {3906}, {12113, 12114, 12112, 12115}, "Enter Blackrock Depths, find and kill Incendis, then report back to Thunderheart.", "The prerequisite is taken from Senani Thunderheart. Incendis is inside the dungeon.", {{48,1}, {52,2}, {54,3}, {59,4}, {67,5}}, {11126}, nil, 9084, "Thunderheart", { xp = 7300, money = 25500, rep = { {81, 150, "Thunder Bluff"} } } },
        { 3981, "H", 48, nil, "Galamav the Marksman", "Badlands - Kargath 5,47", "The Last Element", false, nil, nil, "Enter Blackrock Depths and find Commander Gor'shak — the sketch shows an orc behind iron bars, so look somewhere like a prison.", "The prerequisite comes from Thunderheart (Badlands - Kargath 3,48); Pyron is right before the dungeon entrance. Gor'shak is inside the dungeon. The jail key drops from Interrogator Gerstahn; talking to him to open the next stage spawns mobs.", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, 9081, "Galamav the Marksman", nil },
        { 4003, "H", 48, 59, "Thrall", "Orgrimmar 31,37", "The Royal Rescue", false, {4002}, nil, "Kill Emperor Dagran Thaurissan and free Princess Moira Bronzebeard of Ironforge from her enchantment.", "Talk with Kharan Mustershammer and Thrall first to get the quest. Dagran is inside the dungeon. The princess heals Dagran — never kill the princess, remember to interrupt her healing!", {{48,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 4949, "Thrall", { xp = 8050 } },
        { 4004, "H", 48, 60, "Princess Moira Bronzebeard", nil, nil, true, {4003}, {12544, 12545}, nil, nil, {{48,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 8929, "Princess Moira Bronzebeard", { xp = 9950, money = 27000, rep = { {67, 200, "[UNUSED] Brother Milius"} } } },
        { 4081, "H", 48, 52, "WANTED", "Badlands - Kargath 3,47", nil, false, nil, nil, "Clear Blackrock Depths for Warlord Goretooth: kill 15 Rageforge Guards, 10 Rageforge Jailers and 5 Rageforge Footmen, then report back.", "These dwarves are concentrated in the first half of Blackrock Depths. Goretooth is at the top of the Kargath watchtower (Badlands 5,47).", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, nil, nil, { xp = 5100, money = 15500, rep = { {76, 100, "Orgrimmar"} } } },
        { 4136, nil, 48, 53, "Yuka Screwspigot", "Burning Steppes - Flame Crest 65,22", "Yuka Screwspigot", false, {4324}, {11865, 11963, 12049}, "Bring Ribbly's head to Yuka Screwspigot in the Burning Steppes.", "The quest can be taken directly; the prerequisite comes from Yuka Screwspigot (Tanaris - Steamwheedle Port 67,23). Ribbly is inside the dungeon.", {{48,1}, {49,2}, {51,3}, {56,4}, {64,5}}, {11313}, nil, 9544, "Yuka Screwspigot", { xp = 2650, money = 6000 } },
        { 4242, "A", 48, 54, "Marshal Windsor", nil, "Abandoned Hope", true, {4241}, {12018, 12021, 12041}, nil, "Marshal Windsor is held in a cell inside the dungeon (the key drops from High Interrogator Gerstahn). There is no immediate follow-up after turning this in: go back into BRD and keep killing mobs until 'A Crumpled Up Note' drops to continue the chain.", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9023, "Marshal Windsor", { xp = 5450, rep = { {72, 100, "Stormwind City"} } } },
        { 4262, nil, 48, nil, "Jalinda Sprig", "Burning Steppes - Morgan's Vigil 85,69", nil, false, nil, nil, "Kill Overlord Pyron and report back to Jalinda Sprig.", "Pyron is a fire elemental elite just outside the dungeon entrance.", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, 9561, "Jalinda Sprig", nil },
        { 4263, "A", 48, 56, "Jalinda Sprig", "Burning Steppes - Morgan's Vigil 85,69", "Incendius!", false, {4262}, {12113, 12114, 12112, 12115}, "Enter Blackrock Depths, find and kill Incendis.", "The prerequisite is taken from Jalinda Sprig. Incendis is inside the dungeon.", {{48,1}, {52,2}, {54,3}, {59,4}, {67,5}}, nil, nil, 9561, "Jalinda Sprig", { xp = 5800, money = 8500, rep = { {54, 100, "Gnomeregan Exiles"} } } },
        { 7201, "H", 48, 54, "Shadowmage Vivian Lagrave", "Badlands - Kargath 2,47", "The Last Element", false, {3906}, {12038}, "Collect 10 elemental essences in Blackrock Depths — look on the war golems and golem makers; Vivian Lagrave also mentioned elementals...", "The prerequisite comes from Thunderheart (Badlands - Kargath 3,48); Pyron is right before the dungeon entrance. All elementals can drop the essences.", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, {11129}, nil, 9078, "Shadowmage Vivian Lagrave", { xp = 5450, money = 24500, rep = { {68, 100, "Undercity"} } } },
        { 4082, "H", 50, 54, "WANTED", "Badlands - Kargath 3,47", "KILL ON SIGHT: High Ranking Dark Iron Officials", false, {4081}, nil, "Clear Blackrock Depths for Warlord Goretooth: kill 10 Rageforge Medics, 10 Rageforge Soldiers and 10 Rageforge Officers, then report back.", "The Rageforge dwarves are near Belga. Goretooth is at the top of the Kargath watchtower (Badlands 5,47); the chain starts with Rexlot (Badlands - Kargath 5,47). Grark Lorkrub is in the Burning Steppes (38,35): bring him below 50% health and bind him to start the escort (elite).", {{50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, nil, nil, { xp = 5450, money = 16500, rep = { {76, 100, "Orgrimmar"} } } },
        { 4123, nil, 50, 55, "Maxwort Uberglint", "Burning Steppes - Flame Crest 65,23", nil, false, nil, nil, "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", "The Heart of the Mountain is in the chest of the Black Vault. You must first clear all the small chests of the Black Vault and defeat the boss that appears to get the key.", {{50,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {11309}, nil, 9536, "Maxwort Uberglint", { xp = 5650, money = 8500 } },
        { 4126, "A", 50, 55, "Ragnar Thunderbrew", "Dun Morogh - Kharanos 46,52", "Ragnar Thunderbrew", false, {4128}, {11964, 12000, 12003}, "Bring the Lost Thunderbrew Recipe back to Ragnar Thunderbrew in Kharanos.", "The prerequisite comes from Ennohar Thunderbrew (Blasted Lands - Nethergarde Keep 61,18). Destroying the Thunderbrew kegs spawns guards; the recipe is on one of them.", {{50,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {11312}, nil, 1267, "Ragnar Thunderbrew", { xp = 7050, money = 16500 } },
        { 4134, "H", 50, 55, "Shadowmage Vivian Lagrave", "Badlands - Kargath 2,47", "Vivian Lagrave", false, {4133}, {11964, 12000, 3928, 6149}, "Bring the Lost Thunderbrew Recipe to Shadowmage Vivian Lagrave in Kargath.", "The prerequisite is given by Apothecary Zinge (Undercity - The Apothecarium 50,68). After smashing the barrels Hurley shows up with elite guards, and EVERY spawned guard drops a recipe (one per party member); if you wipe, the barrels despawn and the instance must be reset to try again.", {{50,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {11312}, nil, 9078, "Shadowmage Vivian Lagrave", { xp = 5650, money = 8500 } },
        { 4201, nil, 50, 54, "Mistress Nagmara", "Blackrock Depths", nil, true, nil, {11962, 11866}, "Bring 4 Gromsbloods, 10 Large Silver Veins and Nagmara's filled bottle to Mistress Nagmara in Blackrock Depths.", "Mine the Large Silver Veins from the giants of Azshara; ask a herbalist player for the Gromsblood; fill the bottle at the Golakka Hot Springs in Un'Goro Crater (31,50). After turning in you can take the back door directly — no need to kill Farrax again.", {{50,2}, {52,3}, {57,4}, {65,5}}, {8846, 11405, 11413, 11412}, nil, 9500, "Mistress Nagmara", { xp = 5450, money = 8000 } },
        { 4264, "A", 50, 58, "Starts from the item [Crumpled Note]", nil, nil, false, nil, nil, nil, "'A Crumpled Up Note' drops randomly inside BRD. Marshal Windsor is in the BRD prison — don't mix the two up: Marshal Maxwell is at Morgan's Vigil in the Burning Steppes.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11446}, nil, nil, nil, { xp = 6200, rep = { {72, 100, "Stormwind City"} } } },
        { 4282, "A", 50, 58, "Marshal Windsor", nil, nil, true, {4264}, nil, nil, nil, {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11464, 11465}, nil, 9023, "Marshal Windsor", { xp = 6200, money = 9000, rep = { {72, 100, "Stormwind City"} } } },
        { 4286, "A", 50, 56, "Oralius", "Burning Steppes - Morgan's Vigil 84,68", nil, false, nil, {11883}, "Find 20 Dark Iron satchels in Blackrock Depths, then report back to Oralius.", "All Dark Iron dwarves can drop the satchels.", {{50,1}, {52,2}, {54,3}, {59,4}, {67,5}}, {11468}, nil, 9177, "Oralius", { xp = 5800, money = 8500, rep = { {47, 100, "Ironforge"} } } },
        { 4322, "A", 50, 58, "Marshal Windsor", nil, nil, true, nil, {12061, 12062, 12065}, nil, "Before starting the Jail Break (the Windsor escort), make sure everyone in the party has turned in the previous quest, or some members won't get credit. After completing it you MUST talk to Windsor before leaving the dungeon — running straight out means doing it all over again.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9023, "Marshal Windsor", { xp = 7750, money = 17500, rep = { {72, 150, "Stormwind City"} } } },
        { 4341, nil, 50, nil, "King Magni Bronzebeard", "Ironforge 39,55", "Kharan Mighthammer", false, {3701}, nil, "Find Kharan Mustershammer in Blackrock Depths — the king says he is guarding prisoners there, so look near the jail.", "The chain starts with Royal Historian Archesonus (Ironforge 38,55). Kharan Mustershammer is inside the dungeon.", {{50,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 2784, "King Magni Bronzebeard", nil },
        { 4362, "A", 50, 59, "King Magni Bronzebeard", "Ironforge 39,55", "The Fate of the Kingdom", false, {4361}, nil, "Return to Blackrock Depths and rescue Princess Moira Bronzebeard of Ironforge from Emperor Dagran Thaurissan.", "The princess is inside the dungeon. During the fight she heals Dagran — interrupt it when you can, but never let her die or the quest fails. After the rescue, return to Magni Bronzebeard in Ironforge to report.", {{50,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 2784, "King Magni Bronzebeard", { xp = 8050, rep = { {47, 150, "Ironforge"} } } },
        { 4363, "A", 50, 59, "Princess Moira Bronzebeard", nil, nil, true, {4362}, {12548, 12543}, nil, nil, {{50,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 8929, "Princess Moira Bronzebeard", { xp = 9650, money = 26500 } },
        { 4024, nil, 52, 58, "Cyrus Therepentous", "Burning Steppes 95,31", "A Taste of Flame", false, {4022}, {12066, 12082, 12083}, "Enter Blackrock Depths and kill Belga, use the special black dragonhide to harvest the Fire Essence from the corpse, and bring it to Cyrus Therepentous.", "The chain starts with Kharan Mighthammer (Burning Steppes 39,38). Bael'Gar is inside the dungeon. Don't forget to use the molt item from your bags while standing on Bael'Gar's corpse — it's easy to miss.", {{52,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11230, 11231}, nil, 9459, "Cyrus Therepentous", { xp = 6200, money = 26500 } },
        { 4063, "H", 52, 58, "Lotwil Veriatus", "Badlands 25,44", "The Rise of the Machines", false, {4062}, {12109, 12110, 12108, 12111}, "Kill Puppetmaster Aggemancur and bring his head to Lotwil Veriatus; also collect 10 Intact Elemental Cores from the golems guarding him.", "The prerequisite comes from Sage Sedola Muwadanni (Badlands - Kargath 3,47). Aggemancur is inside the dungeon.", {{52,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11268, 11269}, nil, 2921, "Lotwil Veriatus", { xp = 6200, money = 26500 } },
        { 4121, "H", 52, 58, "Grark Lorkrub", "Burning Steppes", "Grark Lorkrub", false, {4122}, nil, nil, nil, {{52,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11286}, nil, 9520, "Grark Lorkrub", { xp = 7750, money = 26500, rep = { {76, 150, "Orgrimmar"} } } },
        { 4132, "H", 52, 58, "Warlord Goretooth", "Badlands - Kargath 5,47", "Operation: Death to Angerforge", false, {4121}, {12059}, "Enter Blackrock Depths and kill General Angerforge, then report back to Warlord Goretooth.", "General Angerforge is inside the dungeon. Note: he summons reinforcements below 30% health!", {{52,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9077, "Warlord Goretooth", { xp = 7750, money = 26500, rep = { {76, 150, "Orgrimmar"} } } },
        { 7848, nil, 55, nil, "Lothos Riftwaker", "Blackrock Mountain dungeon entrance map", nil, false, nil, nil, "Enter Blackrock Depths, find a Molten Fragment near the portal to the Molten Core, and bring it back to Lothos Riftwaker at Blackrock Mountain.", "After completing this you can use the teleport stone beside Lothos Riftwaker to enter the Molten Core directly. The fragment is inside the dungeon.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18412}, nil, 14387, "Lothos Riftwaker", nil },
        { 9015, nil, 58, 60, "Falrin Treeshaper", "Dire Maul: West, the Library", "The Challenge", false, {8950}, nil, "Go to the Blackrock Depths arena and plant the taunting banner in the center while Adjudicator Griston passes judgment; kill Thalren and his warriors, then bring the first Vasalak Amulet back to Anhein Hamo in the Eastern Plaguelands.", "The follow-ups differ by class. Arena event: when the yell goes out, plant the Banner of Provocation in the center of the arena to start the fight. ◎ The chest MUST be looted first by the person on the quest, otherwise nobody can loot the trinket (player-reported).", {{58,3}, {63,4}, {72,5}}, {22047, 21986}, nil, 16032, "Falrin Treeshaper", { xp = 6600 } },
        { 7604, nil, 60, 60, "Lokhtos Darkbargainer", "Blackrock Depths", nil, false, nil, {18592}, "If you want the Sulfuron designs, hand the Thorium Brotherhood Covenant to Rocktus Darkpact.", "Signing the covenant requires a Sulfuron Ingot — dropped by Golemagg the Incinerator of the Molten Core.", {{60,3}, {63,4}, {72,5}}, {18628, 17203}, nil, nil, nil, { xp = 6600, rep = { {59, 200, "Shambling Skeleton UNUSED"} } } },
        { 4241, nil, 75, nil, "Abandoned Hope", "Drops from Coren Direbrew", nil, false, {4224}, nil, "Bring Coren's Brew to Epikug Ironkeg at the Brewfest camp near Ironforge.", "Available only during Brewfest; the quest item can be taken once per character. Epikug Ironkeg is at the Brewfest camp (Dun Morogh 47,39).", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9560, "Marshal Maxwell", nil },
    },
    ["dire_maul_east"] = {
        { 7441, nil, 54, 58, "Azj'Tordin", "Feralas - The Lariss Pavilion 76,37", nil, false, nil, {18411, 18410}, "Find the imp Pusillin in Dire Maul and retrieve Azj'Tordin's grimoire by any means.", "Pusillin is in Dire Maul: East; it runs as soon as you talk to it — chase it a stretch and it will stop and become attackable. It also drops the Crescent Key — the door key for Dire Maul North and West.", {{54,2}, {56,3}, {61,4}, {69,5}}, {18261}, nil, 14355, "Azj'Tordin", { xp = 7750, money = 17500, rep = { {809, 200, "Shen'dralar"} } } },
        { 7488, "A", 54, 57, "Latronicus Moonspear", "Feralas - Feathermoon Stronghold 30,46", "Lethtendris's Web", false, {7494}, {18491}, "Bring Lethtendris's Web to Latronicus Moonspear at Feathermoon Stronghold in Feralas.", "Lethtendris is in Dire Maul: East. The prerequisite can be taken from the courier Koley Foghammer in Ironforge.", {{54,2}, {55,3}, {60,4}, {68,5}}, {18426}, nil, 7877, "Latronicus Moonspear", { xp = 7550, money = 17000, rep = { {469, 150, "[UNUSED] Brother Milius"} } } },
        { 7489, "H", 54, 57, "Talo Thornhoof", "Feralas - Camp Mojache 76,43", "Lethtendris's Web", false, {7492}, {18491}, "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", "Lethtendris is in Dire Maul: East. The prerequisite is taken from Herald Golarak in Orgrimmar.", {{54,2}, {55,3}, {60,4}, {68,5}}, {18426}, nil, 7776, "Talo Thornhoof", { xp = 7550, money = 17000, rep = { {67, 150, "[UNUSED] Brother Milius"} } } },
