        { 6163, "H", 56, 60, "Nathanos Blightcaller", "Eastern Plaguelands 22,68", "Ramstein", false, {6135}, {18022, 17001}, "Kill Ramstein the Gorger in Stratholme and bring his head to Nathanos.", "The prerequisite is likewise taken from Nathanos. Ramstein is inside the instance.", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "Nathanos Blightcaller", { xp = 6600, money = 18000, rep = { {68, 100, "Undercity"} } } },
        { 5463, nil, 57, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands - Light's Hope Chapel 75,52", "Menethil's Gift", false, {5462}, nil, "Find Menethil's Gift in Stratholme and place the lich's mortal remains on that evil ground.", "The prerequisite is from Magistrate Marduke (Western Plaguelands - Caer Darrow 70,73). The mark is the pentagram on the floor of the Baron's room. See also 'Lich Ras Frostwhisper' in Scholomance.", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 6600 } },
        { 8945, nil, 58, 60, "Ysida Harmon", "Eastern Plaguelands - Stratholme", "Dead Man's Plea", false, {8929}, {22137}, "Enter Stratholme and rescue Ysida Harmon from Baron Rivendare.", "Ysida Harmon stands right at the instance entrance; you need the Extraplanar Ghost Revealer to see her. Prerequisite: Alliance talks to Deliana (Ironforge 43,52), Horde to Mokvar (Orgrimmar 38,37). This is also the famous \"45-minute Baron\" run.", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "Anthion Harmon", { xp = 8300 } },
        { 8968, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "Vital Materials", false, {8964}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and the left half of the Vatalak Trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8991, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "More Vital Materials", false, {8987}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and Duke Vatalak's trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7622, nil, 60, nil, "Eris Havenfire", "Eastern Plaguelands 17,14", "The Balance of Light and Shadow", false, {7621}, nil, "Save 50 farmers before 15 of them are killed, then talk to Eris Havenfire when done. The death notices show your rescue progress.", "You need the Eye of Divinity (from the chest of the Firelord in Molten Core) to meet Eris Havenfire and take the quest. On completion, combine the Eye of Divinity, the Splinter of Nordrassil and the Eye of Shadow (random demon drops in Blasted Lands / Winterspring) to obtain the priest epic staff — Benediction.", {{60,3}, {63,4}, {72,5}}, nil, "Priest", 14494, "Eris Havenfire", nil },
        { 9257, nil, 60, nil, "Anachronos", "Tanaris - Caverns of Time 65,49", "Atiesh, Greatstaff of the Guardian", false, {9251}, nil, "Anachronos of the Caverns of Time in Tanaris wants you to travel to Stratholme, use Atiesh, Greatstaff of the Guardian on the hallowed ground, defeat the creatures driven out, then report back to him.", "The summoning spot is inside the instance. In the Wrath of the Lich King expansion this quest can no longer be obtained; only the \"summon Atiesh\" step remains completable.", {{60,3}, {63,4}, {72,5}}, {22737}, "Priest", nil, nil, nil },
    },
    ["upper_blackrock_spire"] = {
        { 4788, nil, 40, 58, "Prospector Ironboot", "Tanaris - Steamwheedle Port 66,23", "The Final Tablets", false, {5065}, nil, "Bring the fifth and sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", "The 5th tablet is in Shadow Hunter Vosh'gajin's room, the 6th in War Master Voone's room. The reward comes from 'Facing Yeh'kinya'; Yeh'kinya is right beside Prospector Ironboot.", {{40,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {12740, 12741}, nil, 10460, "Prospector Ironboot", { xp = 7750 } },
        { 6502, "A", 50, 60, "Haleh", "Winterspring", "Drakefire Amulet", false, {6501}, {16309}, nil, nil, {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10929, "Haleh", { xp = 8300 } },
        { 4729, nil, 55, 59, "Kibler", "Burning Steppes - Flame Crest 65,22", nil, false, nil, {12264}, "Trap the Bloodaxe worg pups in Blackrock Spire: use the cage to subdue the little ones and bring the caged pup to Kibler.", "The worg pups are inside the dungeon.", {{55,2}, {57,3}, {62,4}, {71,5}}, {12263, 12262}, nil, 10260, "Kibler", { xp = 6400, money = 9000 } },
        { 4862, nil, 55, 59, "Kibler", "Burning Steppes - Flame Crest 65,22", nil, false, nil, {12529}, "Collect 15 Spirestone Spider Eggs for Kibler in Blackrock Spire.", "The spider eggs are inside the dungeon. Looting an egg can randomly spawn small spiders — they hit hard and have an AOE, watch out.", {{55,2}, {57,3}, {62,4}, {71,5}}, {12530}, nil, 10260, "Kibler", { xp = 6400, money = 9000 } },
        { 4866, nil, 55, 60, "Ragged John", "Burning Steppes - Flame Crest 65,23", nil, false, nil, {15873}, "Find the Queen of the Smokeweb at the heart of Blackrock Spire and fight her so she injects venom into you; kill her too if you can. Once poisoned, return to Ragged John and have him draw out the \"Queen's Milk\".", "The Queen of the Smokeweb is inside the dungeon. Note: cleansing the poison midway fails the quest.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9563, "Ragged John", { xp = 9950, money = 18000 } },
        { 4974, "H", 55, 60, "Thrall", "Orgrimmar 31,38", "For The Horde!", false, {4941}, {13966, 13968, 13965}, "Kill Warchief Rend Blackhand in Blackrock Spire and return to Orgrimmar with his head.", "Rend Blackhand is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12630}, nil, 4949, "Thrall", { xp = 9950, money = 27000, rep = { {76, 200, "Orgrimmar"}, {530, 200, "Darkspear Trolls"}, {68, 200, "Undercity"}, {81, 200, "Thunder Bluff"} } } },
        { 4982, "H", 55, 59, "Bijou", "Lower Blackrock Spire", "Bijou's Belongings", true, {4981}, nil, "Recover Bijou's device and return it to her — she remembers hiding it in the lowest level of the city.", "The device is on the way to the Queen of the Smokeweb.", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "Bijou", { xp = 6400 } },
        { 4983, "H", 55, 59, "Bijou", nil, nil, true, {4982}, {15858, 15859}, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12652}, nil, 10257, "Bijou", { xp = 6400, money = 18000, rep = { {76, 100, "Orgrimmar"} } } },
        { 5001, "A", 55, 59, "Bijou", "Lower Blackrock Spire", nil, true, nil, nil, "Recover Bijou's device and return it to her. Good luck!", "The device is on the way to the Queen of the Smokeweb. Afterwards see Marshal Maxwell (Burning Steppes - Morgan's Vigil 84,58).", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "Bijou", { xp = 6400 } },
        { 5002, "A", 55, 59, "Bijou", nil, nil, true, {5001}, nil, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12770}, nil, 10257, "Bijou", { xp = 6400, money = 18000, rep = { {72, 100, "Stormwind City"} } } },
        { 5047, nil, 55, 60, "Finkle Einhorn", "Upper Blackrock Spire", nil, true, nil, nil, "Talk with Marevus Darkhammer in Everlook.", "Fink Enhall only appears after the Beast has been skinned. Marevus Darkhammer is at Winterspring - Everlook (61,38).", {{57,2}, {58,3}, {63,4}, {72,5}}, {12710}, nil, 10776, "Pip Quickwit", { xp = 6600 } },
        { 5102, "A", 55, 60, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 82,68", "General Drakkisath's Demise", false, {5089}, {13966, 13968, 13965}, "Kill General Drakkisath in Blackrock Spire and report back to Marshal Maxwell.", "General Drakkisath is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9560, "Marshal Maxwell", { xp = 9950, money = 27000, rep = { {469, 200, "[UNUSED] Brother Milius"} } } },
        { 5127, nil, 55, 60, "Lorax", "Winterspring 64,74", "The Demon Forge", false, {5126}, {12696, 9224, 12849}, "Find Gularuk in Blackrock Spire; after killing him, thrust the Bloodstained Spear into the corpse to drain its soul and forge the Soulpiercer; then find an unforged Runed Breastplate and bring both to Lorax in Winterspring.", "Blacksmithing quest. Goraluk is inside the dungeon. Requires Blacksmithing 270 to pick up.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12847, 12806, 12848}, nil, 10918, "Lorax", { xp = 8300 } },
        { 6569, "H", 55, nil, "Myranda the Hag", "Western Plaguelands 50,77", "Oculus Illusions", false, {6568}, nil, "Collect 20 Black Dragon Whelp eyes in Blackrock Spire, then report back to Myranda the Hag.", "All black dragonkin drop the eyes.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16786}, nil, 11872, "Myranda the Hag", { xp = 6600 } },
        { 6602, "H", 55, 60, "Rokaro", "Desolace - Shadowprey Village 25,71", "Blood of the Black Dragon Champion", false, {6601}, {16309}, "Kill General Drakkisath in Blackrock Spire and bring his blood to Rokaro.", "The final step of the Onyxia prerequisite chain. General Drakkisath is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10182, "Rokaro", { xp = 9950 } },
        { 6821, nil, 55, nil, "Duke Hydraxis", "Azshara 79,73", "Eye of the Emberseer", false, nil, nil, "Bring the Eye of Ebohir to Duke Hydraxis in Azshara.", "Ebohir is inside the instance. This quest chain can no longer be started after patch 3.0.8; characters who already have it are unaffected and can still complete it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {17322}, nil, 13278, "Duke Hydraxis", nil },
        { 7761, nil, 55, nil, nil, "Blackhand's Command drops from the Scarshield Quartermaster (on the dungeon entrance map).", nil, false, nil, nil, "What a dim-witted orc — find the brand and obtain Drakkisath's Badge before you can use the Orb of Command.", "The Blackwing Lair attunement quest. The Scarshield Quartermaster is near the right side of the Blackrock Spire entrance; the orb is behind General Drakkisath.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18987}, nil, nil, nil, nil },
        { 4734, nil, 57, 60, "Tinkee Steamboil", "Burning Steppes - Flame Crest 65,24", "Tinkee Steamboil", false, {4907}, {12144}, "Use the Egg Freezer Mark I on a dragon egg in the hatchery.", "The eggs are in the Father Flame's room. After freezing an egg do NOT click it — use the device from your backpack; after killing General Drakkisath you can jump straight down to the rookery and finish it separately.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12286}, nil, 10267, "Tinkee Steamboil", { xp = 8300, money = 18000, rep = { {169, 150, "Steamwheedle Port"} } } },
        { 4735, nil, 57, 60, "Tinkee Steamboil", "Burning Steppes - Flame Crest 65,24", "Egg Collection", false, {4734}, nil, "Bring the Electric Collection Module and 8 dragon eggs to Tinkee Steamboil at Flame Crest in the Burning Steppes.", "The eggs are all in the Father Flame's room. After freezing an egg, get close and use the device from your backpack (don't click the egg); if the raid won't wait, jump down to the rookery after the General to finish it solo.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12241, 12287}, nil, 10267, "Tinkee Steamboil", { xp = 9950, money = 27000, rep = { {169, 200, "Steamwheedle Port"} } } },
        { 4743, nil, 57, 60, "Acride", nil, "Seal of Ascension", true, {4742}, {12344}, nil, "Use the Unforged Seal in the water below the dragon to start the forging event. Each event yields only ONE lootable forged seal, and the dragon has a 3-hour cooldown — only one person can do it per night.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12324, 12339}, nil, 10299, "Acride", { xp = 9950 } },
        { 4764, "A", 57, 60, "Mayara Brightwing", "Burning Steppes - Morgan's Vigil 84,69", "Mayara Brightwing", false, {4766}, nil, "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", "The prerequisite can be taken from Lord Remington Ridgewell (Stormwind City - Stormwind Keep 77,47). The clasp is in the chest in the Father Flame's room. The chest respawns about every 20 seconds, so multiple party members can open it in turn.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12352}, nil, 9565, "Mayara Brightwing", { xp = 1650, rep = { {72, 25, "Stormwind City"} } } },
        { 4765, "A", 57, 60, "Mayara Brightwing", "Burning Steppes", nil, false, {4764}, {15861, 15860}, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {12437}, nil, 9565, "Mayara Brightwing", { xp = 6600, money = 27000, rep = { {72, 100, "Stormwind City"} } } },
        { 4768, "H", 57, 60, "Vivian Lagrave", "Badlands - Kargath 2,47", "The Darkstone Tablet", false, {4769}, {15861, 15860}, "Bring the Darkstone Tablet to Shadowmage Vivian Lagrave in Kargath.", "The prerequisite can be taken from Apothecary Zinge (Undercity - The Apothecarium 50,68). The tablet is in the UBRS rookery (the hatchery).", {{57,2}, {58,3}, {63,4}, {72,5}}, {12358}, nil, 9078, "Shadowmage Vivian Lagrave", { xp = 8300, money = 27000, rep = { {68, 150, "Undercity"} } } },
        { 5160, nil, 57, 60, "Awbee", "Upper Blackrock Spire", nil, true, nil, nil, "Find Haleh in Winterspring and bring her Awbee's scale.", "Awbee is in the room beside the arena, crouching on a ledge. Haleh is in Winterspring (54,51); take the teleport rune at the very back of the cave to reach her.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12923}, nil, 10740, "Awbee", { xp = 6600 } },
        { 8966, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "Vital Materials", false, {8962}, nil, "Use the summoning brazier to call out Mor Grayhoof's spirit and kill him; bring the brazier and the left half of the Vatalak Trinket back to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Mor Grayhoof is summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22049}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8989, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8986}, nil, "Use the summoning brazier in the Beast's room to call out Duke Vatalak; after killing him, use the Vatalak Trinket on the corpse, then return the trinket to the Spirit of Duke Vatalak.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Mor Grayhoof is summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22049}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8994, nil, 58, nil, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "The Right Half of the Vatalak Trinket", false, {8989}, nil, "Collect 40 Blackrock bracers from the orcs of Blackrock Spire and hand them, together with 1 Super Energy Potion, to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The bracers drop from Blackrock Spire orcs; the Super Energy Potion is an alchemy product.", {{58,3}, {63,4}, {72,5}}, {22138, 13512, 22048}, nil, 16033, "Bodley", nil },
        { 8995, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "The Final Preparation", false, {8994}, nil, "Use the summoning brazier in the Beast's room to call out Duke Vatalak; after killing him, use the Vatalak Trinket on the corpse, then return the trinket to the Spirit of Duke Vatalak.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Duke Vatalak is summoned inside the dungeon; claim the reward from Bodley.", {{58,3}, {63,4}, {72,5}}, {22048, 22056}, nil, 16033, "Bodley", { xp = 9950 } },
    },
}

